import java.util.ArrayList;
import java.util.List;

public class Main {
    // --- Approach A: Painful Manual Array Expansion ---
    public static int[] appendToArray(int[] original, int newElement) {
        // Allocate new array with size + 1
        int[] newBuffer = new int[original.length + 1];
        // Copy existing elements
        System.arraycopy(original, 0, newBuffer, 0, original.length);
        // Insert new element at the tail
        newBuffer[original.length] = newElement;
        return newBuffer;
    }

    public static void main(String[] args) {
        System.out.println("=== 1. Manual Array Resizing ===");
        int[] numbers = new int[2];
        numbers[0] = 10;
        numbers[1] = 20;

        // Adding 30 requires manual array reallocation!
        numbers = appendToArray(numbers, 30);
        System.out.println("Array length after resize: " + numbers.length);
        System.out.println("Last element: " + numbers[numbers.length - 1]);

        System.out.println("\n=== 2. Collections Approach (ArrayList) ===");
        List<Integer> list = new ArrayList<>();
        list.add(10);
        list.add(20);
        list.add(30); // Seamless dynamic expansion behind the scenes!
        list.add(40);

        System.out.println("List size: " + list.size());
        System.out.println("Contains 30? " + list.contains(30));
        System.out.println("List content: " + list);
    }
}

