import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public class Main {
    public static void main(String[] args) {
        String[] initialItems = {"Java", "Python", "C++"};
        List<String> languages = new ArrayList<>();
        Collections.addAll(languages, initialItems);

        languages.add("Rust");
        languages.add("Go");
        languages.remove("C++");

        System.out.println("Active Languages (" + languages.size() + "): " + languages);
    }
}

