import java.util.ArrayList;
import java.util.List;

public class Main {
    public static void main(String[] args) {
        int[] rawScores = {62, 88, 74, 91, 55, 75, 100, 49};
        List<Integer> passingScores = new ArrayList<>();
        double sum = 0;

        for (int score : rawScores) {
            if (score >= 75) {
                passingScores.add(score);
                sum += score;
            }
        }

        double average = passingScores.isEmpty() ? 0 : sum / passingScores.size();
        System.out.println("Passing Count: " + passingScores.size());
        System.out.println("Passing Scores: " + passingScores);
        System.out.printf("Passing Average: %.1f\n", average);
    }
}

