    public static String[] insertAtEnd(String[] arr, String newItem) {
        String[] result = new String[arr.length + 1];
        System.arraycopy(arr, 0, result, 0, arr.length);
        result[arr.length] = newItem;
        return result;
    }

    public static void main(String[] args) {
        String[] original = {"Alpha", "Beta"};
        String[] updated = insertAtEnd(original, "Gamma");
        System.out.println(String.join(" -> ", updated));
    }
}

