class ElasticLedger {
    private String[] transactions = new String[2];
    private int size = 0;
    private int resizeCount = 0;

    public void record(String tx) {
        if (size == transactions.length) {
            String[] expanded = new String[transactions.length * 2];
            System.arraycopy(transactions, 0, expanded, 0, transactions.length);
            transactions = expanded;
            resizeCount++;
        }
        transactions[size++] = tx;
    }

    public void printAuditReport() {
        System.out.println("Total Recorded: " + size);
        System.out.println("Buffer Capacity: " + transactions.length);
        System.out.println("Resize Events: " + resizeCount);
    }
}

public class Main {
    public static void main(String[] args) {
        ElasticLedger ledger = new ElasticLedger();
        ledger.record("TX-101");
        ledger.record("TX-102");
        ledger.record("TX-103");
        ledger.record("TX-104");
        ledger.record("TX-105");
        ledger.printAuditReport();
    }
}

